  "inlineSchema": "// schema.prisma\n// this file is basically the whole database in one place, handy ngl\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  ADMIN\n  PM\n  DEVELOPER\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  DONE\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  role         Role\n  createdAt    DateTime @default(now())\n\n  // relations - prisma makes these free basically\n  createdProjects Project[]         @relation(\"ProjectCreator\")\n  assignedTasks   Task[]            @relation(\"TaskAssignee\")\n  activityLogs    TaskActivityLog[]\n  notifications   Notification[]\n  refreshTokens   RefreshToken[]\n}\n\n// keeping refresh tokens in DB not memory so we can revoke on logout\n// (also survives server restarts, learned that one the hard way before)\nmodel RefreshToken {\n  id        String   @id @default(uuid())\n  tokenHash String\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  revoked   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\nmodel Client {\n  id        String    @id @default(uuid())\n  name      String\n  createdAt DateTime  @default(now())\n  projects  Project[]\n}\n\nmodel Project {\n  id          String   @id @default(uuid())\n  name        String\n  clientId    String\n  client      Client   @relation(fields: [clientId], references: [id])\n  createdById String\n  createdBy   User     @relation(\"ProjectCreator\", fields: [createdById], references: [id])\n  createdAt   DateTime @default(now())\n  tasks       Task[]\n\n  @@index([createdById]) // PM's \"give me my own projects\" query hits this constantly\n}\n\nmodel Task {\n  id           String     @id @default(uuid())\n  title        String\n  description  String?\n  projectId    String\n  project      Project    @relation(fields: [projectId], references: [id])\n  assignedToId String?\n  assignedTo   User?      @relation(\"TaskAssignee\", fields: [assignedToId], references: [id])\n  status       TaskStatus @default(TODO)\n  priority     Priority   @default(MEDIUM)\n  dueDate      DateTime?\n  isOverdue    Boolean    @default(false) // flipped by the cron job, not on the fly\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  activityLogs  TaskActivityLog[]\n  notifications Notification[]\n\n  // these 4 indexes exist bc the filter bar (status/priority/duedate) and\n  // the dashboards all query on these columns constantly. without them\n  // this thing crawls once seed data grows past a few hundred rows\n  @@index([projectId])\n  @@index([assignedToId])\n  @@index([status])\n  @@index([priority])\n  @@index([dueDate])\n}\n\n// this is the actual \"who did what when\" log. the activity feed\n// reads FROM this table, it never derives status history from anywhere else\nmodel TaskActivityLog {\n  id         String      @id @default(uuid())\n  taskId     String\n  task       Task        @relation(fields: [taskId], references: [id])\n  userId     String\n  user       User        @relation(fields: [userId], references: [id])\n  fromStatus TaskStatus?\n  toStatus   TaskStatus\n  createdAt  DateTime    @default(now())\n\n  // composite index bc feed queries always do \"logs for x ordered by time\"\n  @@index([taskId, createdAt])\n}\n\nmodel Notification {\n  id            String   @id @default(uuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id])\n  type          String // \"TASK_ASSIGNED\" | \"TASK_IN_REVIEW\" - keeping it a string, not worth an enum here\n  message       String\n  relatedTaskId String?\n  relatedTask   Task?    @relation(fields: [relatedTaskId], references: [id])\n  isRead        Boolean  @default(false)\n  createdAt     DateTime @default(now())\n\n  @@index([userId, isRead]) // the unread-count badge hits this on literally every page load\n}\n",
